/**
 * Sweep harness: provision one throwaway game server for <family> on node-2.
 * Usage: npx tsx provision.ts <family>
 * Prints a single JSON line with { serverId, hostname, family, planId }.
 */
import { db } from "/opt/nxeon/lib/db";

const NODE2 = "cmto2zpwh0000hltqk6oaxy69";
const OPS_USER = "cmrztujaw0002hlazl58i3lsi";

(async () => {
  const family = process.argv[2];
  if (!family) throw new Error("usage: provision.ts <family>");

  const gamePlan = await db.gamePlan.findFirst({
    where: { gameFamily: family },
    orderBy: { priceCents: "asc" },
  });
  if (!gamePlan) {
    console.log(JSON.stringify({ family, skip: "no-gameplan" }));
    await db.$disconnect();
    return;
  }

  // hostname: /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i and <= 40 chars
  const stamp = Date.now().toString(36);
  const hostname = `t-${family.replace(/[^a-z0-9]/gi, "")}-${stamp}`.slice(0, 40).replace(/-$/, "");

  const server = await db.server.create({
    data: {
      name: hostname,
      hostname,
      userId: OPS_USER,
      planId: gamePlan.basePlanId,
      osTemplateId: gamePlan.osTemplateId,
      gamePlanId: gamePlan.id,
      nodeId: NODE2,
      isFree: true,
      termPromoPercent: 100,
    },
  });
  await db.job.create({ data: { type: "PROVISION", serverId: server.id } });

  console.log(
    JSON.stringify({
      serverId: server.id,
      hostname,
      family,
      planId: gamePlan.id,
      planName: gamePlan.name,
    })
  );
  await db.$disconnect();
})().catch((e) => {
  console.error(e);
  process.exit(1);
});
