/**
 * Sweep harness: dump a test server's connection details + port forwards.
 * Writes the root password to <scratch>/pw-<serverId> (mode 600) and prints
 * everything else as JSON — the password is NEVER printed.
 * Usage: npx tsx info.ts <serverId>
 */
import { db } from "/opt/nxeon/lib/db";
import { decryptSecret } from "/opt/nxeon/lib/crypto-box";
import { GAME_PORT, type GameFamily } from "/opt/nxeon/lib/games";
import { writeFileSync, chmodSync } from "node:fs";

const SCRATCH = "/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/sweep";

(async () => {
  const serverId = process.argv[2];
  if (!serverId) throw new Error("usage: info.ts <serverId>");
  const s = await db.server.findUnique({
    where: { id: serverId },
    select: {
      id: true,
      hostname: true,
      status: true,
      vmid: true,
      ipAddress: true,
      sshPort: true,
      rootPassword: true,
      rootPasswordEnc: true,
      gameVariant: true,
      gameConfig: true,
      dedicatedIp: { select: { address: true } },
      node: { select: { publicIp: true, name: true, pveNode: true, isPrimary: true } },
      gamePlan: { select: { gameFamily: true, name: true } },
      osTemplate: { select: { family: true, name: true } },
      plan: { select: { ramMB: true, cpuCores: true, diskGB: true } },
    },
  });
  if (!s) throw new Error(`server ${serverId} not found`);

  const pw = s.rootPassword ?? decryptSecret(s.rootPasswordEnc);
  const pwFile = `${SCRATCH}/pw-${serverId}`;
  if (pw) {
    writeFileSync(pwFile, pw, "utf8");
    chmodSync(pwFile, 0o600);
  }

  const family = (s.gamePlan?.gameFamily ?? s.osTemplate?.family) as GameFamily | undefined;
  const gp = family ? GAME_PORT[family] : undefined;

  const forwards = await db.portForward.findMany({
    where: { serverId },
    select: { id: true, publicPort: true, guestPort: true, protocol: true },
    orderBy: { guestPort: "asc" },
  });

  console.log(
    JSON.stringify(
      {
        id: s.id,
        hostname: s.hostname,
        status: s.status,
        vmid: s.vmid,
        privateIp: s.ipAddress,
        sshPort: s.sshPort,
        dedicatedIp: s.dedicatedIp?.address ?? null,
        node: s.node,
        family,
        gamePlan: s.gamePlan?.name,
        plan: s.plan,
        gamePort: gp,
        gameVariant: s.gameVariant,
        gameConfig: s.gameConfig,
        forwards,
        pwFile: pw ? pwFile : null,
        gamePortForward: gp ? forwards.find((f) => f.guestPort === gp.port && f.protocol === gp.protocol) ?? null : null,
      },
      null,
      2
    )
  );
  await db.$disconnect();
})().catch((e) => {
  console.error(e);
  process.exit(1);
});
